def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 45.0))
        return float(min(budget, 12.0))

    prev_bids = []
    aggressive_bids = []
    active_threats = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 95:
                aggressive_bids.append(float(bid))
        if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
            active_threats += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0
    high_anchor = max(aggressive_bids) if aggressive_bids else highest_prev

    units = int(supply // WATER_REQ)
    tight_supply = units <= 1

    emergency = hp <= 2 or no_water_days >= 1
    fragile = hp <= 4

    if emergency:
        target = max(110.0, high_anchor + 2.0)
        if tight_supply:
            target = max(target, 128.0)
        return float(min(budget, target))

    if fragile and tight_supply:
        target = max(96.0, avg_prev * 0.92)
        return float(min(budget, target))

    if tight_supply:
        if highest_prev >= 120:
            target = 18.0
        else:
            target = 28.0
        return float(min(budget, target))

    if active_threats >= 2 and highest_prev >= 100:
        return float(min(budget, 10.0))

    return float(min(budget, 16.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    avg_opp_bid = 0
    count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            avg_opp_bid += prev['bid']
            count += 1

    baseline = (avg_opp_bid / count) + 5.0 if count > 0 else 40.0

    if supply < 18:
        bid = min(my_status['budget'], max(baseline, 65.0))
    elif supply < 22:
        bid = min(my_status['budget'], max(baseline, 45.0))
    else:
        bid = min(my_status['budget'], max(baseline * 0.8, 25.0))

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)

    return float(bid)
